import test from 'node:test';
import assert from 'node:assert/strict';
import { formatPhoneNumber } from './submission.mjs';

test('should correctly format valid 10-digit phone numbers', () => {
  assert.strictEqual(formatPhoneNumber('1234567890'), '(123) 456-7890', 'Basic 10 digits');
  assert.strictEqual(formatPhoneNumber('(123) 456-7890'), '(123) 456-7890', 'Already formatted input');
  assert.strictEqual(formatPhoneNumber('123-456-7890'), '(123) 456-7890', 'Input with hyphens');
  assert.strictEqual(formatPhoneNumber(' 123 456 7890 '), '(123) 456-7890', 'Input with spaces');
  assert.strictEqual(formatPhoneNumber(' (123) - 456 - 7890 '), '(123) 456-7890', 'Input with mixed ignored characters');
});

test('should throw TypeError for invalid phone number inputs', () => {
  assert.throws(() => formatPhoneNumber('12345'), TypeError, 'Too few digits');
  assert.throws(() => formatPhoneNumber('12345678901'), TypeError, 'Too many digits');
  assert.throws(() => formatPhoneNumber('123a456789'), TypeError, 'Contains non-digit characters');
  assert.throws(() => formatPhoneNumber(''), TypeError, 'Empty string');
  assert.throws(() => formatPhoneNumber('() - '), TypeError, 'Only ignored characters');
  assert.throws(() => formatPhoneNumber('123456789'), TypeError, 'Exactly 9 digits');
  assert.throws(() => formatPhoneNumber('123456789012'), TypeError, 'Exactly 12 digits');
});
